function pendulumWindow(st,p=0){const z=pendulumZones(st,p);if(!z.L||!z.R)return{ok:false,reason:'Se requieren 2 Escalas Péndulo activas.'};const a=scaleValue(z.L.card,'L'),b=scaleValue(z.R.card,'R'),lo=Math.min(a,b),hi=Math.max(a,b);if(lo===hi)return{ok:false,reason:'Las Escalas son iguales; no existe intervalo de Nivel.'};return{ok:true,left:a,right:b,low:lo,high:hi,zones:z}}
function pendulumEligible(st,p=0){const w=pendulumWindow(st,p);if(!w.ok)return{...w,hand:[],extra:[]};const between=c=>{const n=lvl(c);return n>w.low&&n<w.high};const hand=zone(st,'hand',p).filter(x=>isMonster(x.card)&&between(x.card));const extra=zone(st,'extra',p).filter(x=>isPendulum(x.card)&&x.faceUp===true&&between(x.card));return{...w,hand,extra}}
function canPendulumSummon(st,p=0,uids=[]){if(!phaseOK(st,p))return{ok:false,reason:'Pendulum Summon solo se representa durante tu Main Phase.'};if(store(st).pendulumUsed[p])return{ok:false,reason:'Ya realizaste una Pendulum Summon este turno.'};const e=pendulumEligible(st,p);if(!e.ok)return e;const uniq=[...new Set((uids||[]).map(String))];if(!uniq.length)return{ok:false,reason:'No se seleccionaron monstruos.'};const H=new Set(e.hand.map(x=>String(x.uid))),X=new Set(e.extra.map(x=>String(x.uid)));let handN=0,extraN=0;for(const id of uniq){if(H.has(id))handN++;else if(X.has(id))extraN++;else return{ok:false,reason:`${id} no es elegible para Pendulum Summon con esas Escalas.`}}const main=freeMainSlots(st,p).length;if(handN>main)return{ok:false,reason:'No hay suficientes Main Monster Zones para los monstruos de la mano.'};const remainingMain=main-handN,extraCapacity=(emzOccupied(st,p)?0:1)+Math.min(remainingMain,linkedMainCapacity(st,p));if(extraN>extraCapacity)return{ok:false,reason:'Los Monstruos Péndulo boca arriba del Extra Deck requieren EMZ o zonas enlazadas disponibles.'};return{ok:true,...e,handN,extraN,extraCapacity}}
function pendulumSummon(st,p=0,uids=[]){const chk=canPendulumSummon(st,p,uids);if(!chk.ok)return chk;const ids=[...new Set(uids.map(String))],moved=[];let mains=freeMainSlots(st,p);let emzFree=!emzOccupied(st,p);let linked=linkedMainCapacity(st,p);for(const id of ids){const q=locate(st,id);if(!q)continue;const from=q.z,it=zone(st,q.z,q.p).splice(q.i,1)[0];it.previousZone=from;it.controller=p;it.faceUp=true;it.position='ATK';it.summonType='PENDULUM_SUMMON';it.summonTurn=st.turn;it.summonPlayer=p;if(from==='hand'){it.__alpha307Slot=mains.shift()||null}else{if(emzFree){it.__alpha307Slot='EMZ';emzFree=false}else if(linked>0&&mains.length){it.__alpha307Slot=mains.shift();linked--}else return{ok:false,reason:'La asignación de zona Péndulo desde Extra quedó sin capacidad.'}}delete it.__alpha317PendulumZone;zone(st,'monster',p).push(it);moved.push({uid:id,from,slot:it.__alpha307Slot,name:it.card?.name})}
 store(st).pendulumUsed[p]=true;store(st).pendulumActions.push({type:'PENDULUM_SUMMON',uids:ids,turn:st.turn});if(st.analysis){st.analysis.successfulSummons=(st.analysis.successfulSummons||0)+moved.length;st.analysis.actions=(st.analysis.actions||0)+1}emit(st,'PENDULUM_SUMMON',{player:p,uids:ids,moved,scales:[chk.left,chk.right]});return{ok:true,moved,scales:[chk.left,chk.right]}}
function resetPendulumTurn(st,p){store(st).pendulumUsed[p]=false}
const oldAdvance=R.advance?.bind(R);if(oldAdvance)R.advance=function(st,...args){const beforeTurn=Number(st.turn)||0,beforePlayer=Number(st.activePlayer)||0;const r=oldAdvance(st,...args);if((Number(st.turn)||0)!==beforeTurn||Number(st.activePlayer)!==beforePlayer)resetPendulumTurn(st,Number(st.activePlayer)||0);return r};

function isFusionSubstitute(card){const s=low(text(card));return /substitute (?:this card )?for any 1 fusion[- ]material|used as a substitute for any 1 fusion material/.test(s)&&/other (?:fusion )?material(?: monster)?\(s\)? must be correct|other materials must be correct/.test(s)}
function fusionSubMode(card){const s=low(text(card));if(/whose name is mentioned on the fusion monster card/.test(s))return'NAMED_ONLY';if(/any 1 fusion[- ]material monster/.test(s))return'ANY_ONE';return isFusionSubstitute(card)?'NAMED_ONLY':null}
function materialSegments(fusion){const first=String(text(fusion)||'').split(/\r?\n/)[0].trim();if(!first||!first.includes('+'))return[];return first.split(/\s*\+\s*/).map(x=>x.trim()).filter(Boolean).map(raw=>({raw,names:quoted(raw),count:Number(raw.match(/^(\d+)\+?\s+/)?.[1]||1)}))}
function identityMatches(st,item,raw){const v=C316.effectiveProperties(st,item.uid),s=low(raw),qs=quoted(raw);if(qs.length){if(!qs.some(q=>v?.names?.some(n=>norm(n)===norm(q))||v?.archetypes?.some(a=>norm(a)===norm(q))))return false}const meta=low(`${v?.race||''} ${v?.attribute||''} ${item.card?.type||''} ${(v?.archetypes||[]).join(' ')} ${(v?.names||[]).join(' ')}`);for(const race of ['dragon','warrior','spellcaster','fiend','fairy','machine','cyberse','beast','aqua','rock','plant','zombie','wyrm','illusion'])if(new RegExp(`\\b${race}\\b`).test(s)&&!meta.includes(race))return false;for(const a of ['dark','light','earth','water','fire','wind','divine'])if(new RegExp(`\\b${a}\\b`).test(s)&&low(v?.attribute)!==a)return false;if(/effect monster/.test(s)&&!/effect/.test(ctype(item.card))&&!text(item.card).trim())return false;if(/normal monster/.test(s)&&!/normal/.test(ctype(item.card)))return false;return isMonster(item.card)}
function chooseSets(arr,k,limit=24){const out=[];function go(i,cur){if(out.length>=limit)return;if(cur.length===k){out.push(cur.slice());return}for(let j=i;j<arr.length;j++){cur.push(arr[j]);go(j+1,cur);cur.pop();if(out.length>=limit)return}}if(k>0&&k<=arr.length)go(0,[]);return out}
function fusionMaterialAssignments(st,fusion,p=0,zones=['hand','monster']){const segs=materialSegments(fusion);if(!segs.length)return[];const pool=zones.flatMap(z=>zone(st,z,p).map(it=>({it,z}))).filter(x=>isMonster(x.it.card));const out=[];function rec(si,used,chosen,subUsed){if(out.length>=48)return;if(si>=segs.length){out.push({entries:chosen.slice(),substituteUsed:subUsed});return}const seg=segs[si],need=Math.max(1,Number(seg.count)||1);const exact=pool.filter(x=>!used.has(x.it.uid)&&identityMatches(st,x.it,seg.raw));for(const set of chooseSets(exact,need,18)){const nu=new Set(used);for(const x of set)nu.add(x.it.uid);rec(si+1,nu,[...chosen,...set],subUsed)}if(!subUsed){const substitutes=pool.filter(x=>!used.has(x.it.uid)&&isFusionSubstitute(x.it.card));for(const sub of substitutes){const mode=fusionSubMode(sub.it.card),named=seg.names.length>0;if(!(mode==='ANY_ONE'||(mode==='NAMED_ONLY'&&named)))continue;if(need===1){const nu=new Set(used);nu.add(sub.it.uid);rec(si+1,nu,[...chosen,sub],true)}else{const rest=exact.filter(x=>x.it.uid!==sub.it.uid);for(const set of chooseSets(rest,need-1,12)){const nu=new Set(used);nu.add(sub.it.uid);for(const x of set)nu.add(x.it.uid);rec(si+1,nu,[...chosen,sub,...set],true)}}}}}rec(0,new Set(),[],false);return out}
function sourceFusionCards(st,p=0){return [...zone(st,'hand',p),...zone(st,'spelltrap',p)].filter(x=>isSpell(x.card)&&/fusion summon/i.test(text(x.card))&&/(hand|field)/i.test(text(x.card)))}
function consumeToGy(st,uid){const q=locate(st,uid);if(!q)return null;const it=zone(st,q.z,q.p).splice(q.i,1)[0];it.previousZone=q.z;if(q.z==='monster'&&isPendulum(it.card)){it.faceUp=true;delete it.__alpha317PendulumZone;zone(st,'extra',it.owner??q.p).push(it)}else zone(st,'gy',it.owner??q.p).push(it);return it}
function fusionSubstituteSummon(st,p,fusionUid,sourceUid,materialUids){const fq=locate(st,fusionUid),sq=locate(st,sourceUid);if(!fq||fq.p!==p||fq.z!=='extra'||!isFusion(fq.item.card))return{ok:false,reason:'Fusion Monster no disponible en el Extra Deck.'};if(!sq||sq.p!==p||!sourceFusionCards(st,p).some(x=>x.uid===sourceUid))return{ok:false,reason:'No hay un efecto de Fusion Summon compatible representado.'};const sets=fusionMaterialAssignments(st,fq.item.card,p,['hand','monster']);const want=[...materialUids].map(String).sort().join('|'),match=sets.find(s=>s.entries.map(x=>String(x.it.uid)).sort().join('|')===want);if(!match)return{ok:false,reason:'Los materiales no cumplen la receta ni la regla de sustituto de Fusión.'};const main=freeMainSlots(st,p);if(!main.length&&!emzOccupied(st,p)){}else if(!main.length)return{ok:false,reason:'No hay zona disponible para el Fusion Monster.'};for(const x of match.entries)consumeToGy(st,x.it.uid);const fq2=locate(st,fusionUid);const fusion=zone(st,fq2.z,fq2.p).splice(fq2.i,1)[0];fusion.faceUp=true;fusion.position='ATK';fusion.controller=p;fusion.summonType='FUSION_SUMMON';fusion.summonTurn=st.turn;fusion.summonPlayer=p;fusion.__alpha307Slot=main.shift()||'EMZ';zone(st,'monster',p).push(fusion);consumeToGy(st,sourceUid);store(st).fusionSubstitutions.push({fusionUid,sourceUid,materials:materialUids,substituteUsed:!!match.substituteUsed});if(st.analysis){st.analysis.successfulSummons=(st.analysis.successfulSummons||0)+1;st.analysis.materialsUsed=(st.analysis.materialsUsed||0)+materialUids.length;st.analysis.actions=(st.analysis.actions||0)+1}emit(st,'FUSION_SUMMON_SUBSTITUTE',{player:p,fusionUid,sourceUid,materials:materialUids,substituteUsed:!!match.substituteUsed});return{ok:true,fusion,substituteUsed:!!match.substituteUsed}}

function targetIdentityMatch(st,item,description){const s=low(description),v=C316.effectiveProperties(st,item.uid);if(!v)return false;const qs=quoted(description);if(qs.length&&!qs.some(q=>v.names?.some(n=>norm(n)===norm(q))||v.archetypes?.some(a=>norm(a)===norm(q))))return false;const named=s.match(/(?:"|“)([^"”]+)(?:"|”)/);if(named&&!qs.length&&!v.names?.some(n=>norm(n)===norm(named[1])))return false;return true}
function identityTargetPool(st,p,description){const s=low(description),opp=/opponent|adversary|adversario|oponente/.test(s)?1-p:p;let arr;if(/hand|mano/.test(s))arr=[...zone(st,'hand',opp)];else if(/graveyard|cementerio/.test(s))arr=[...zone(st,'gy',opp)];else if(/banished|desterrad/.test(s))arr=[...zone(st,'banished',opp)];else if(/deck|mazo/.test(s))arr=[...zone(st,'deck',opp)];else if(/extra deck|deck extra/.test(s))arr=[...zone(st,'extra',opp)];else arr=[...zone(st,'monster',opp),...zone(st,'spelltrap',opp)];if(/monster|monstruo/.test(s))arr=arr.filter(x=>isMonster(x.card));return arr.filter(x=>targetIdentityMatch(st,x,description))}
const activate316=R.activate.bind(R);R.activate=function(st,p,c,uid,effectId,targets=[],costs=[]){const e=R.parseCard(c).effects?.find(x=>x.id===effectId);if(e&&targets?.length&&e.targets?.length){for(const t of e.targets){const pool=new Set(identityTargetPool(st,p,t.description).map(x=>String(x.uid)));const chosen=targets.filter(x=>pool.has(String(x)));const min=typeof t.count==='number'?t.count:(t.count?.min||0);if(quoted(t.description).length&&chosen.length<min)return{ok:false,reason:'El objetivo elegido no coincide con el nombre/arquetipo efectivo requerido.'}}}return activate316(st,p,c,uid,effectId,targets,costs)};
R.alpha317LegalIdentityTargets=identityTargetPool;
R.alpha317MatchesRequirement=(st,uid,req)=>{const q=locate(st,uid);return!!q&&identityMatches(st,q.item,req)};
R.alpha317PlacePendulumScale=placeScale;R.alpha317PendulumSummon=pendulumSummon;R.alpha317PendulumEligible=pendulumEligible;R.alpha317FusionAssignments=fusionMaterialAssignments;R.alpha317FusionSubstituteSummon=fusionSubstituteSummon;


function candidateShape(st,actions,line,score,opening=[]){const v=A308.verify?A308.verify({st,actions}):{ok:true,errors:[]};const q=Math.max(0,Math.min(100,Math.round(score)));return{line,actions,score:q,finalScore:q,state:st,verified:!!v.ok,status:v.ok?'VERIFICADO · REGLAS 317':'NO VERIFICADO',verification:v,simulation:{state:st,openingHand:opening,actions,executed:actions.map(a=>a.card),legal:!!v.ok,finalBoard:A307.finalBoard(st)}}}
function pendulumMechanicCandidates(seedNode,limit=5){const out=[],base=seedNode?.st||seedNode?.state;if(!base)return out;const opening=seedNode?.opening||seedNode?.simulation?.openingHand||[];const hand=zone(base,'hand',0).filter(x=>isPendulum(x.card));for(let i=0;i<hand.length;i++)for(let j=i+1;j<hand.length;j++){if(out.length>=limit)return out;const li=scaleValue(hand[i].card,'L'),rj=scaleValue(hand[j].card,'R');if(li===rj)continue;const st=clone(base),prior=seedNode.actions||[];let before=A307.snapshot(st),r1=placeScale(st,0,hand[i].uid,'L');if(!r1.ok)continue;const ac1=A307.actionRecord(st,before,hand[i].card,null,'PENDULUM SCALE',{ok:true,status:'RESUELTA'},{effectText:`Escala izquierda ${li}.`});before=A307.snapshot(st);let r2=placeScale(st,0,hand[j].uid,'R');if(!r2.ok)continue;const ac2=A307.actionRecord(st,before,hand[j].card,null,'PENDULUM SCALE',{ok:true,status:'RESUELTA'},{effectText:`Escala derecha ${rj}.`});const eligible=pendulumEligible(st,0);if(!eligible.ok)continue;const free=freeMainSlots(st,0).length,extraCap=(emzOccupied(st,0)?0:1)+Math.min(free,linkedMainCapacity(st,0));const ids=[...eligible.hand.slice(0,free).map(x=>x.uid),...eligible.extra.slice(0,extraCap).map(x=>x.uid)];if(!ids.length)continue;before=A307.snapshot(st);const r=pendulumSummon(st,0,ids);if(!r.ok)continue;const ac3=A307.actionRecord(st,before,{name:'Pendulum Summon'},null,'PENDULUM SUMMON',{ok:true,status:'RESUELTA'},{materials:ids,effectText:`Invoca simultáneamente Niveles entre ${eligible.low} y ${eligible.high}; Péndulos del Extra respetan EMZ/zona enlazada.`});const line=[...(seedNode.line||[]),hand[i].card,hand[j].card,...r.moved.map(x=>locate(st,x.uid)?.item?.card).filter(Boolean)];out.push(candidateShape(st,[...prior,ac1,ac2,ac3],line,A307.boardValue(st)+8,opening))}return out}
function fusionMechanicCandidates(seedNode,limit=5){const out=[],base=seedNode?.st||seedNode?.state;if(!base)return out;const opening=seedNode?.opening||seedNode?.simulation?.openingHand||[];const sources=sourceFusionCards(base,0),fusions=zone(base,'extra',0).filter(x=>isFusion(x.card));for(const src of sources){for(const f of fusions){if(out.length>=limit)return out;const sets=fusionMaterialAssignments(base,f.card,0,['hand','monster']).filter(x=>x.substituteUsed);for(const set of sets){if(out.length>=limit)return out;const st=clone(base),before=A307.snapshot(st),r=fusionSubstituteSummon(st,0,f.uid,src.uid,set.entries.map(x=>x.it.uid));if(!r.ok)continue;const fq=locate(st,f.uid)?.item||f;const action=A307.actionRecord(st,before,fq.card,null,'FUSION SUMMON',{ok:true,status:'RESUELTA'},{materials:set.entries.map(x=>x.it.uid),effectText:`Fusion Summon con 1 sustituto legal; todos los demás materiales cumplen la receta impresa.`});out.push(candidateShape(st,[...(seedNode.actions||[]),action],[...(seedNode.line||[]),src.card,f.card],A307.boardValue(st)+7,opening))}}}return out}
function mechanicsSearch(baseCandidates=[]){const nodes=[];for(const r of baseCandidates.slice(0,5))nodes.push({st:clone(r.state||r.st),actions:clone(r.actions||[]),line:clone(r.line||[]),opening:r.simulation?.openingHand||[]});for(let i=0;i<4;i++){try{const st=A307.openingState(i);nodes.push({st,actions:[],line:[],opening:zone(st,'hand',0).map(x=>({name:x.card?.name,id:x.card?.id,card:x.card}))})}catch(_){}}
 const extra=[];for(const n of nodes){extra.push(...pendulumMechanicCandidates(n,3),...fusionMechanicCandidates(n,3));if(extra.length>=18)break}return extra.filter(x=>x.verified)}
function enrichCandidate317(r){const st=r.state||r.simulation?.state;if(!st)return r;let stress=0,prot=0,rel=0,prop=0,id=0;try{stress=W.YGOAlpha310?.stressLine?.(r)?.score||0}catch(_){}try{prot=W.YGOAlpha313?.protectionScore?.(st)||0}catch(_){}try{rel=W.YGOAlpha314?.Core?.relationScore?.(st)||0}catch(_){}try{prop=W.YGOAlpha315?.Core?.propertyScore?.(st)||0}catch(_){}try{id=W.YGOAlpha316?.Core?.identityScore?.(st)||0}catch(_){}const mech=mechanicsScore(st),base=Number(r.alpha316RankScore??r.alpha315RankScore??r.finalScore??r.score)||0;r.alpha317MechanicsScore=mech;r.alpha317Stress=stress;r.alpha317RankScore=Math.round(base+mech+prot*.25+rel*.25+prop*.25+id*.25+stress*.04);r.status=`${r.verified?'VERIFICADO':'RECHAZADO'} · REGLAS 317 · PÉNDULO/FUSIÓN ${mech>=0?'+':''}${mech} · ${r.status||''}`;return r}

