const norm=s=>String(s??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’]/g,"'").replace(/[“”]/g,'"').replace(/[^a-z0-9]+/g,' ').trim();
function mergeCatalog(input=W.CARD_CATALOG){
 const arr=Array.isArray(input)?input.slice():[],byId=new Map();
 for(const c of arr){const id=Number(c?.id)||0;if(id&&!byId.has(id))byId.set(id,c)}
 for(const d0 of DELTA){const d={...d0},id=Number(d.id)||0,old=byId.get(id);if(old){const merged={...old,...d,archetypes:[...new Set([...(old.archetypes||[]),...(d.archetypes||[])])],legacyNames:[...new Set([...(old.legacyNames||[]),old.name].filter(x=>x&&norm(x)!==norm(d.name))) ]};const i=arr.indexOf(old);if(i>=0)arr[i]=merged;byId.set(id,merged)}else{arr.push(d);byId.set(id,d)}}
 const seen=new Set(),out=[];for(const c of arr){const id=Number(c?.id)||0,key=id?'id:'+id:'nm:'+norm(c?.name);if(seen.has(key))continue;seen.add(key);out.push(c)}
 out.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));return out;
}
function mergeNow(){W.CARD_CATALOG=mergeCatalog(W.CARD_CATALOG);return W.CARD_CATALOG}
