function specialAllowed(st,p,it){const L=st?.__alpha340Locks?.[p]||{};if(L.attribute&&attrOf(it)!==L.attribute)return false;if(L.archetype&&!isArch(it,L.archetype))return false;return true}
function special(st,p,uid,opts={}){const q=locate(st,uid);if(!q)return{ok:false,reason:'Carta objetivo no localizada.'};if(!freeMonster(st,p))return{ok:false,reason:'No hay zona de monstruo disponible.'};if(!specialAllowed(st,p,q.item))return{ok:false,reason:'Una restricción activa impide esta Invocación Especial.'};const it=moveUid(st,uid,'monster',p,{faceUp:true,position:opts.position||'ATK'});if(!it)return{ok:false,reason:'No se pudo Invocar de Modo Especial.'};it.specialSummoned=true;it.summonType=opts.summonType||'EFFECT';if(opts.summonedBy)it.summonedBy=opts.summonedBy;if(st?.analysis)st.analysis.successfulSummons=(st.analysis.successfulSummons||0)+1;return{ok:true,item:it,uid:it.uid}}
function sendSourceSpell(st,src,p){if(src&&['hand','spelltrap'].includes(src.z))return moveUid(st,src.item.uid,'gy',p);return src?.item||null}
function isEcclesia(x){return /ecclesia/i.test(nameOf(x))}
function mentionsAlbaz(x){return /fallen of albaz/i.test(textOf(x))}
function isBrandedST(x){return (isSpell(x)||isTrap(x))&&(isArch(x,'Branded')||/branded/i.test(nameOf(x)))}

