 if(mode.includes('place trap')||mode.includes('quick')){if(used(st,p,nameOf(src.item),'PLACE_TRAP'))return{ok:false,reason:'El efecto de colocar Trampa ya fue usado.'};const q=findTarget(st,p,['deck','gy'],x=>isContinuousTrap(x)&&isArch(x,'Radiant Typhoon'),ctx.targetUid);if(!q)return{ok:false,reason:'No hay Trampa Continua Radiant Typhoon válida.'};const it=moveUid(st,q.item.uid,'spelltrap',p,{faceUp:true});it.__alpha340ContinuousTrap=true;mark(st,p,nameOf(src.item),'PLACE_TRAP');return{ok:true,placed:nameOf(it)}}
